/* Die skins as base64 so they work over file:// too. Firefox gives every
   local file its own origin, so an external image is cross-origin and
   WebGL refuses to upload it - the same reason die.glb ships embedded.
   Sources are Denis's PNGs in Art/Assets/3D/textures/<name>/. */
window.FK_DIE_SKINS={
  amber:{map:'data:image/jpeg;base64,',
         spec:'data:image/jpeg;base64,'}
};
